\label{prop:transfer}
	Suppose $(Y^\mathbb F,Z^\mathbb F)$ solves \eqref{eq:FBSDE}
	and satisfies
	\begin{equation}\label{eq:transfercondition}
		\int_0^T|Z_s^\mathbb F\alpha_s|\,ds<\infty
		\quad\text{almost surely}.
	\end{equation}
	Then the same pair satisfies, in the enlarged
	filtration $\mathbb G$,
	\begin{equation}\label{eq:transferred}
		Y_t^\mathbb F=\xi+\int_t^T
		\big[f(s,Y_s^\mathbb F,Z_s^\mathbb F)-Z_s^\mathbb F\alpha_s\big]\,ds
		-\int_t^T Z_s^\mathbb F\,dW_s.
	\end{equation}
	The identity holds up to indistinguishability.
	No uniqueness for \eqref{eq:transferred}
	is asserted.

\label{thm:value}
	For every deterministic $t\in[0,T]$,
	\begin{equation}\label{eq:value}
		\mathbb E[S_t^{\mathbb G}\mid\mathcal F_t]
		\ge S_t^{\mathbb F}
		\qquad \mathbb P\text{-a.s.}
	\end{equation}
	In particular, $\mathbb E [S_0^{\mathbb G}]\ge\mathbb E [S_0^{\mathbb F}]$.
